  "decision_type": "action",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "The model exploits trial-specific signatures (e.g., shared task direction) rather than subject identity.",
      "mechanism": "Trial-level information transfer allows high window accuracy even when windows are split from the same trial, whereas random labels at the trial level should destroy this signal.",
      "supporting_evidence_ids": ["obs_1"],
      "limitations": "Does not rule out domain-specific mappings that happen to align with trials."
    },
    {
      "id": "H2",
      "claim": "The model exploits subject identity or session-level artifacts.",
      "mechanism": "Performance relies on unseen subjects/sessions in the test set, which should degrade significantly under a trial split where all windows of a trial are held out together (subject split is stricter).",
      "supporting_evidence_ids": ["obs_1"],
      "limitations": "Does not rule out trial-specific signatures that co-vary with subjects."
    }
  ],
  "action": {
    "request_id": "req_1",
    "tool_id": "trial_random_labels",
    "parameters": {},
    "distinguishes": ["H1", "H2"],
    "prediction": {
      "scoring_status": "numeric",
      "metric_key": "trial_random_trial_ba_mean",
      "primary_direction": "near_zero",
      "threshold": 0.05,
      "conditional_predictions": [
        {"hypothesis_id": "H1", "direction": "positive", "rationale": "If trial-specific signatures exist, randomizing labels at the trial level should not destroy performance if the signature is structural (e.g., task direction) rather than label-dependent. However, since we are testing for signal transfer to new trials, a positive gap suggests H1."},
        {"hypothesis_id": "H2", "direction": "negative", "rationale": "If subject identity drives performance, randomizing labels at the trial level (which preserves subjects) might still show high accuracy if subjects are preserved. But since we want to distinguish between trial-specific and subject-specific, a near-zero or negative result suggests H1 is more likely."}
      ],
      "update_rule_if_opposite": "If `trial_random_trial_ba_mean` > 0.5 + threshold (positive), it supports H2; if < 0.5 - threshold (negative), it supports H1."
    }
  },
  "stop": null,
  "reasoning_summary": "Compare trial-randomized performance to baseline: high accuracy suggests subject/session artifacts (H2); near-chance or low accuracy suggests trial-specific signatures (H1). Use `trial_random_trial_ba_mean` as the primary metric."
}

